def solve(coins, amount):
    # Fewest coins summing to amount (unlimited supply of each value), or -1.
    # Classic unbounded-knapsack / coin-change dynamic programming.
    INF = float('inf')
    dp = [0] + [INF] * amount
    for i in range(1, amount + 1):
        for c in coins:
            if 0 < c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

