def solve(grid):
    """Count number of islands in a binary grid.
    An island is a group of 1s connected orthogonally.
    Args:
        grid (list of list of int): 0/1 values.
    Returns:
        int: number of islands.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < cols:
                    if not visited[ni][nj] and grid[ni][nj] == 1:
                        stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

def solve(s: str) -> str:
    if not s:
        return ''
    n = len(s)
    start = 0
    max_len = 1
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - 1
    for i in range(n):
        # odd length
        l1, r1 = expand(i, i)
        len1 = r1 - l1 + 1
        if len1 > max_len or (len1 == max_len and l1 < start):
            start, max_len = l1, len1
        # even length
        l2, r2 = expand(i, i + 1)
        len2 = r2 - l2 + 1
        if len2 > max_len or (len2 == max_len and l2 < start):
            start, max_len = l2, len2
    return s[start:start + max_len]

def solve(n, b):
    # Convert integer n to base b (2-36), lowercase digits, '-' for negatives.
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    if n == 0:
        return '0'
    neg = n < 0
    n = abs(n)
    out = []
    while n > 0:
        out.append(digits[n % b])
        n //= b
    if neg:
        out.append('-')
    return ''.join(reversed(out))

