def solve(matrix):
    """Return the determinant of a square integer matrix (list of lists).

    Exact Fraction-based Gaussian elimination with partial pivoting over
    nonzero entries; the exact result is coerced to int. An empty matrix
    (or a matrix of empty rows) has determinant 1.
    """
    from fractions import Fraction

    def to_frac(x):
        try:
            return Fraction(x)
        except (TypeError, ValueError):
            return Fraction(int(x))

    m = [[to_frac(x) for x in row] for row in matrix]
    n = len(m)
    if n == 0:
        return 1
    if all(len(row) == 0 for row in m):
        return 1
    sign = 1
    det = Fraction(1)
    for k in range(n):
        pivot_row = None
        for i in range(k, n):
            if m[i][k] != 0:
                pivot_row = i
                break
        if pivot_row is None:
            return 0
        if pivot_row != k:
            m[k], m[pivot_row] = m[pivot_row], m[k]
            sign = -sign
        pv = m[k][k]
        det *= pv
        for i in range(k + 1, n):
            factor = m[i][k] / pv
            if factor:
                row_i, row_k = m[i], m[k]
                for j in range(k, n):
                    row_i[j] -= factor * row_k[j]
    result = sign * det
    return int(result)

